(2683724, 372126, 42100, '<td valign="top">Great balance to this composition and very nice tones.  Very nice!</td>', 'Great balance to this composition and very nice tones.  Very nice!', '2006-08-01 13:43:14.000000', NULL, 1),
(2683725, 372444, 54731, '<td valign="top">You should have stood on the other side, the shadow on his face is the problem here, other than that very nice!</td>', 'You should have stood on the other side, the shadow on his face is the problem here, other than that very nice!', '2006-08-01 13:43:51.000000', NULL, 1),
