(2687208, 371986, 23430, '<td valign="top">Brilliant composition. The purple light looks a bit wierd though.</td>', 'Brilliant composition. The purple light looks a bit wierd though.', '2006-08-02 06:14:17.000000', NULL, 1),
(2687210, 372045, 23430, '<td valign="top">Lovely detail and colours</td>', 'Lovely detail and colours', '2006-08-02 06:14:45.000000', NULL, 1),
