(2693387, 372234, 48389, '<td valign="top">Nice idea but I feel the feather needs lighting a little better (MHO)</td>', 'Nice idea but I feel the feather needs lighting a little better (MHO)', '2006-08-03 19:56:26.000000', NULL, 1),
(2693392, 372429, 48389, '<td valign="top">I like the simplicity of the apple and the B/G but find the ''line'' of whatever the apple is sitting on a little distracting (MHO)</td>', 'I like the simplicity of the apple and the B/G but find the ''line'' of whatever the apple is sitting on a little distracting (MHO)', '2006-08-03 19:58:11.000000', NULL, 1),
